#!/usr/bin/env node
/**
 * Generates src/data/brand-marks.ts — authentic brand glyphs, inlined as SVG
 * path data, for the platforms Simple Icons still carries.
 *
 * Why generate rather than depend at runtime: Simple Icons is 3,400+ icons and
 * we need a handful, so the generated file ships only the paths we use and the
 * package stays a devDependency.
 *
 * Coverage is genuinely partial — Simple Icons has removed most streaming
 * brands on trademark request and never carried the Indian services. The
 * complete set comes from TMDB's watch-provider logos via fetch-logos.mjs;
 * these fill in beforehand, and anything unmatched keeps its monogram.
 *
 * Usage: node scripts/build-brand-marks.mjs
 */

import { readFile, writeFile } from 'node:fs/promises';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import * as simpleIcons from 'simple-icons';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = resolve(ROOT, 'src/data/brand-marks.ts');

const norm = (s) => s.toLowerCase().replace(/[^a-z0-9]/g, '');

// Match on the platform's own name, then a few aliases where the brand is
// catalogued under a different name than we display it under.
const ALIASES = {
  hbomax: ['max', 'hbo'],
  appletv: ['appletv'],
  paramount: ['paramountplus'],
  prime: ['primevideo', 'amazonprimevideo'],
  disney: ['disneyplus'],
  jiohotstar: ['hotstar', 'disneyhotstar'],
};

const byTitle = new Map();
for (const icon of Object.values(simpleIcons)) {
  if (icon && typeof icon === 'object' && icon.title && icon.path) {
    byTitle.set(norm(icon.title), icon);
  }
}

const src = await readFile(resolve(ROOT, 'src/data/platforms.ts'), 'utf8');
const platforms = [...src.matchAll(/\{\s*id:\s*'([^']+)',\s*name:\s*'([^']+)'/g)].map(
  ([, id, name]) => ({ id, name }),
);

const found = {};
const missing = [];
for (const { id, name } of platforms) {
  const candidates = [norm(name), norm(id), ...(ALIASES[id] ?? [])];
  const hit = candidates.map((c) => byTitle.get(c)).find(Boolean);
  if (hit) found[id] = { path: hit.path, title: hit.title };
  else missing.push(id);
}

const body = `/**
 * GENERATED by scripts/build-brand-marks.mjs — do not edit by hand.
 *
 * Authentic brand glyphs for the platforms Simple Icons carries. Everything
 * else falls back to a monogram until TMDB's provider logos are fetched.
 */

export interface BrandMark {
  /** SVG path data on a 24x24 viewBox. */
  path: string;
  title: string;
}

export const BRAND_MARKS: Record<string, BrandMark> = ${JSON.stringify(found, null, 2)};
`;

await writeFile(OUT, body);
console.log(`Wrote ${Object.keys(found).length} brand marks to ${OUT}:`);
for (const [id, m] of Object.entries(found)) console.log(`  ✓ ${id} → ${m.title}`);
console.log(`\nNo Simple Icons entry for: ${missing.join(', ')}`);
console.log('These keep the monogram until TMDB provider logos are fetched.');
